const source = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

function readPath(obj, path) {
  return path.split('.').reduce((acc, key) => {
    if (acc && typeof acc === 'object' && key in acc) return acc[key];
    return undefined;
  }, obj);
}

function pick(obj, paths, fallback = '') {
  for (const path of paths) {
    const value = readPath(obj, path);
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return String(value).trim();
    }
  }
  return fallback;
}

function pickBool(obj, paths, fallback = false) {
  for (const path of paths) {
    const value = readPath(obj, path);
    if (typeof value === 'boolean') return value;
    if (value === 1 || value === '1') return true;
    if (typeof value === 'string') {
      const normalized = value.trim().toLowerCase();
      if (['true', 'yes', 'sim', 'on'].includes(normalized)) return true;
      if (['false', 'no', 'nao', 'off'].includes(normalized)) return false;
    }
  }
  return fallback;
}

function normalizePhone(phone) {
  const digits = String(phone || '').replace(/\D+/g, '');
  if (!digits) return '';
  return digits.startsWith('55') ? digits : `55${digits}`;
}

function normalizeSqlPhone(fieldName) {
  return `REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(${fieldName}, ''), '(', ''), ')', ''), '-', ''), ' ', ''), '+', '')`;
}

const companyName = 'Sua Assistencia Tecnica';
const erpWebhookUrl = 'https://sistema.seudominio.com/webhooks/whatsapp';
const erpWebhookToken = 'COLE_O_TOKEN_WEBHOOK_ERP';
const erpOrigin = 'https://sistema.seudominio.com';

const menuiaUrl = 'https://chatbot.menuia.com/api';
const menuiaAppKey = 'COLE_O_APPKEY_MENUIA';
const menuiaAuthKey = 'COLE_O_AUTHKEY_MENUIA';

const openaiApiKey = 'COLE_OPENAI_API_KEY';
const openaiModel = 'gpt-4.1-mini';

const phone = normalizePhone(pick(source, [
  'from',
  'sender',
  'phone',
  'telefone',
  'number',
  'author',
  'chat_id',
  'jid',
  'data.from',
  'data.sender',
  'data.phone',
  'data.telefone',
  'data.number',
  'contact.phone',
  'contact.number',
  'data.contact.phone',
  'data.contact.number'
]));

const text = pick(source, [
  'message',
  'mensagem',
  'text',
  'body',
  'caption',
  'conteudo',
  'data.message',
  'data.mensagem',
  'data.text',
  'data.body',
  'data.caption',
  'data.conteudo'
], '');

const normalizedText = text
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

const hasMedia = pickBool(source, ['has_media', 'hasMedia', 'data.has_media', 'data.hasMedia'], false);
const fromMe = pickBool(source, ['from_me', 'fromMe', 'data.from_me', 'data.fromMe'], false);
const selfCheck = pickBool(source, ['self_check', 'data.self_check'], false);
const shouldReply = !fromMe && !selfCheck && phone !== '';
const phoneNoCountry = phone.replace(/^55/, '');

const phoneValuesSql = [phone, phoneNoCountry]
  .filter((value, index, array) => value && array.indexOf(value) === index)
  .map((value) => `'${value.replace(/'/g, "''")}'`)
  .join(', ');

const phoneWhere = [
  normalizeSqlPhone('c.telefone1'),
  normalizeSqlPhone('c.telefone2'),
  normalizeSqlPhone('c.telefone_contato')
].map((expr) => `${expr} IN (${phoneValuesSql || "''"})`).join(' OR ');

const clienteLookupSql = `
SELECT *
FROM (
  SELECT
    1 AS cliente_encontrado,
    c.id,
    c.nome_razao,
    c.email,
    c.telefone1,
    c.telefone2,
    c.nome_contato,
    c.telefone_contato,
    c.cidade,
    c.uf,
    c.observacoes
  FROM clientes c
  WHERE ${phoneWhere}
  ORDER BY c.id DESC
  LIMIT 1
) cliente
UNION ALL
SELECT
  0 AS cliente_encontrado,
  NULL AS id,
  NULL AS nome_razao,
  NULL AS email,
  NULL AS telefone1,
  NULL AS telefone2,
  NULL AS nome_contato,
  NULL AS telefone_contato,
  NULL AS cidade,
  NULL AS uf,
  NULL AS observacoes
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1
  FROM clientes c
  WHERE ${phoneWhere}
  LIMIT 1
)
LIMIT 1;
`.trim();

const erpPayload = {
  ...(typeof source === 'object' ? source : { raw: String(source) }),
  n8n_workflow: 'atendimento-clientes-whatsapp-ai',
  n8n_received_at: new Date().toISOString(),
  normalized_phone: phone,
  normalized_text: text,
  has_media: hasMedia,
  detected_intent: normalizedText
};

return {
  ...$json,
  source,
  companyName,
  normalizedPhone: phone,
  phoneNoCountry,
  receivedText: text,
  normalizedText,
  hasMedia,
  fromMe,
  selfCheck,
  shouldReply,
  erpWebhookUrl,
  erpWebhookToken,
  erpOrigin,
  menuiaUrl,
  menuiaAppKey,
  menuiaAuthKey,
  openaiApiKey,
  openaiModel,
  clienteLookupSql,
  erpPayload
};

const ctx = $('Montar Contexto IA').first().json;
const response = $json || {};

function extractOutputText(payload) {
  if (typeof payload.output_text === 'string' && payload.output_text.trim() !== '') {
    return payload.output_text.trim();
  }

  if (Array.isArray(payload.output)) {
    for (const item of payload.output) {
      if (item && item.type === 'message' && Array.isArray(item.content)) {
        for (const contentItem of item.content) {
          if (typeof contentItem?.text === 'string' && contentItem.text.trim() !== '') {
            return contentItem.text.trim();
          }
          if (typeof contentItem?.output_text === 'string' && contentItem.output_text.trim() !== '') {
            return contentItem.output_text.trim();
          }
        }
      }
    }
  }

  return '';
}

let aiReply = extractOutputText(response);

if (aiReply === '') {
  aiReply = ctx.clienteEncontrado
    ? `Oi, ${ctx.cliente.nome_razao || 'tudo bem'}? Localizei seu cadastro na ${ctx.companyName}. Pode me dizer em que ponto eu posso te ajudar agora?`
    : `Oi. Recebi sua mensagem na ${ctx.companyName}, mas ainda nao localizei cadastro por este numero. Pode me informar seu nome completo para eu continuar o atendimento?`;
}

return {
  ...ctx,
  aiRawResponse: response,
  aiReply,
  menuiaPayload: {
    to: `+${ctx.normalizedPhone}`,
    appkey: ctx.menuiaAppKey,
    authkey: ctx.menuiaAuthKey,
    message: aiReply,
    licence: 'hugocursos',
    sandbox: 'false'
  }
};
